refentry.refsect1:
&reftitle.description;
stringarraystr_replace arraystringsearch arraystringreplace stringarraysubject intcount&null;
यो function ले subject मा रहेका search का सबै उपस्थितिहरूलाई दिइएको replace value ले प्रतिस्थापन गरिएको एउटा string वा array return गर्दछ।
निश्चित string को सट्टा pattern मा आधारित भएर text प्रतिस्थापन गर्न, preg_replace प्रयोग गर्नुहोस्।

  &reftitle.examples;



    str_replace का आधारभूत उदाहरणहरू


<?php
// Provides: <body text='black'>
$bodytag = str_replace("%body%", "black", "<body text='%body%'>");
echo $bodytag, PHP_EOL;

// Provides: Hll Wrld f PHP
$vowels = array("a", "e", "i", "o", "u", "A", "E", "I", "O", "U");
$onlyconsonants = str_replace($vowels, "", "Hello World of PHP");
echo $onlyconsonants, PHP_EOL;

// Provides: You should eat pizza, beer, and ice cream every day
$phrase  = "You should eat fruits, vegetables, and fiber every day.";
$healthy = array("fruits", "vegetables", "fiber");
$yummy   = array("pizza", "beer", "ice cream");

$newphrase = str_replace($healthy, $yummy, $phrase);
echo $newphrase, PHP_EOL;

// Provides: 2
$str = str_replace("ll", "", "good golly miss molly!", $count);
echo $count, PHP_EOL;
?>







    str_replace का सम्भावित समस्याहरू (gotchas) का उदाहरणहरू


<?php
// Order of replacement
$str     = "Line 1\nLine 2\rLine 3\r\nLine 4\n";
$order   = array("\r\n", "\n", "\r");
$replace = '<br />';

// Processes \r\n's first so they aren't converted twice.
$newstr = str_replace($order, $replace, $str);
echo $newstr, PHP_EOL;

// Outputs F because A is replaced with B, then B is replaced with C, and so on...
// Finally E is replaced with F, because of left to right replacements.
$search  = array('A', 'B', 'C', 'D', 'E');
$replace = array('B', 'C', 'D', 'E', 'F');
$subject = 'A';
echo str_replace($search, $replace, $subject), PHP_EOL;

// Outputs: apearpearle pear
// For the same reason mentioned above
$letters = array('a', 'p');
$fruit   = array('apple', 'pear');
$text    = 'a p';
$output  = str_replace($letters, $fruit, $text);
echo $output, PHP_EOL;
?>

  &reftitle.notes;
  &note.bin-safe;

   प्रतिस्थापन क्रमसम्बन्धी समस्या (gotcha)

str_replace ले बायाँबाट दायाँ प्रतिस्थापन गर्ने हुनाले, धेरै प्रतिस्थापनहरू गर्दा यसले पहिले नै घुसाइएको value लाई प्रतिस्थापन गर्न सक्छ। यस दस्तावेजमा रहेका उदाहरणहरू पनि हेर्नुहोस्।



यो function case-sensitive हो। case-insensitive replace का लागि str_ireplace प्रयोग गर्नुहोस्।
